function iterate(r,x0,n){ var x=x0, out=[x]; for(var i=0;i<n;i++){ x=r*x*(1-x); out.push(x); } return out; }
function lyapunov(r,x0,n){ var x=x0, s=0; for(var i=0;i<n;i++){ var deriv=r*(1-2*x); if(deriv>0||deriv<0){ var d=Math.abs(deriv); if(d>0) s+=Math.log(d); } x=r*x*(1-x); } return s/n; }
var EXPORTS={iterate:iterate, lyapunov:lyapunov};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ChaosForgePure = EXPORTS; }
